#!/usr/bin/env python3
"""Reference solver by exhaustive enumeration (small instances only).

Independent of the submitted engine: recomputes routing coefficients directly
from the request using integer arithmetic scaled by lcm(route weight sums).
"""
import itertools
from fractions import Fraction
from math import lcm


def prepare(inst):
    coms = inst['commodities']
    edges = inst['edges']
    nodes = inst['nodes']
    C, E = len(coms), len(edges)
    eidx = {e['id']: i for i, e in enumerate(edges)}
    cidx = {c['id']: i for i, c in enumerate(coms)}
    K = 1
    for c in coms:
        K = lcm(K, sum(r['weight'] for r in c['routes']))
    link = [[0] * E for _ in range(C)]
    for ci, c in enumerate(coms):
        W = sum(r['weight'] for r in c['routes'])
        for r in c['routes']:
            for eid in r['edges']:
                link[ci][eidx[eid]] += r['weight'] * (K // W)
    ing = [[K if c['source'] == n else 0 for c in coms] for n in nodes]
    egr = [[K if c['target'] == n else 0 for c in coms] for n in nodes]
    dem = [[K if ci == j else 0 for ci in range(C)] for j in range(C)]

    def coef(metric, target):
        if metric == 'demand':
            return dem[cidx[target]]
        if metric == 'link':
            return link[eidx[target]]
        if metric == 'ingress':
            return ing[nodes.index(target)]
        return egr[nodes.index(target)]

    obs = []   # (snapshot, coef, lower*K, upper*K, domain)
    for si, sp in enumerate(inst['snapshots']):
        for o in sp['observations']:
            obs.append((si, coef(o['metric'], o['target']),
                        o['lower'] * K, o['upper'] * K, o['domain']))
    cap = [e['capacity'] * K for e in edges]
    return dict(C=C, E=E, S=len(inst['snapshots']), K=K, link=link, obs=obs,
                cap=cap)


def brute(inst):
    P = prepare(inst)
    C, E, S, K = P['C'], P['E'], P['S'], P['K']
    snaps = inst['snapshots']
    ranges = [range(snaps[s]['bounds'][c][0], snaps[s]['bounds'][c][1] + 1)
              for s in range(S) for c in range(C)]
    total = 1
    for r in ranges:
        total *= len(r)
    if total > 400000:
        return None
    link = P['link']
    cap = P['cap']
    obs = P['obs']
    trusted = [o for o in obs if o[4] is None]
    domained = [o for o in obs if o[4] is not None]
    feasible = []
    for combo in itertools.product(*ranges):
        qs = [combo[s * C:(s + 1) * C] for s in range(S)]
        loads = [[sum(link[c][e] * qs[s][c] for c in range(C)) for e in range(E)]
                 for s in range(S)]
        ok = True
        for s in range(S):
            for e in range(E):
                if loads[s][e] > cap[e]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            for (si, coef, lo, hi, _) in trusted:
                v = sum(co * qs[si][c] for c, co in enumerate(coef) if co)
                if v < lo or v > hi:
                    ok = False
                    break
        if not ok:
            continue
        bad = set()
        for (si, coef, lo, hi, d) in domained:
            if d in bad:
                continue
            v = sum(co * qs[si][c] for c, co in enumerate(coef) if co)
            if v < lo or v > hi:
                bad.add(d)
        if len(bad) <= inst['max_faults']:
            feasible.append((qs, loads, bad))
    if not feasible:
        return {'id': inst['id'], 'status': 'infeasible'}
    k = min(len(b) for _, _, b in feasible)
    F = [(q, l, b) for q, l, b in feasible if len(b) == k]

    def rs(v):
        f = Fraction(v, K)
        return '%d/%d' % (f.numerator, f.denominator)

    forced = set(F[0][2])
    possible = set()
    for _, _, b in F:
        forced &= b
        possible |= b
    dem = []
    links = []
    verdicts = []
    status = 'unique'
    for s in range(S):
        drow = []
        for c in range(C):
            vals = [q[s][c] for q, _, _ in F]
            lo, hi = min(vals), max(vals)
            if lo != hi:
                status = 'ambiguous'
            drow.append([lo, hi])
        dem.append(drow)
        lrow = []
        for e in range(E):
            vals = [l[s][e] for _, l, _ in F]
            lrow.append([rs(min(vals)), rs(max(vals))])
        links.append(lrow)
        ctrl = snaps[s]['controller']
        tol = snaps[s]['tolerance']
        yes = any(all(abs(q[s][c] - ctrl[c]) <= tol for c in range(C))
                  for q, _, _ in F)
        no = any(not all(abs(q[s][c] - ctrl[c]) <= tol for c in range(C))
                 for q, _, _ in F)
        verdicts.append('undetermined' if (yes and no) else
                        ('consistent' if yes else 'inconsistent'))
    wq, wl, wb = F[0]
    witness = {'demands': [list(wq[s]) for s in range(S)],
               'links': [[rs(wl[s][e]) for e in range(E)] for s in range(S)],
               'faults': sorted(wb)}
    alt = None
    if status == 'ambiguous':
        for q, l, b in F:
            if q != wq:
                alt = {'demands': [list(q[s]) for s in range(S)],
                       'links': [[rs(l[s][e]) for e in range(E)] for s in range(S)],
                       'faults': sorted(b)}
                break
    return {'id': inst['id'], 'status': status, 'min_faults': k,
            'faults': {'forced': sorted(forced), 'possible': sorted(possible)},
            'snapshots': [{'id': snaps[s]['id'], 'demands': dem[s],
                           'links': links[s], 'verdict': verdicts[s]}
                          for s in range(S)],
            'witness': witness, 'alternative': alt}


def compare(expected, actual):
    errs = []
    if expected['status'] != actual.get('status'):
        return [('status', expected['status'], actual.get('status'))]
    if expected['status'] == 'infeasible':
        return errs
    if expected['min_faults'] != actual.get('min_faults'):
        errs.append(('min_faults', expected['min_faults'], actual.get('min_faults')))
    for key in ('forced', 'possible'):
        if sorted(expected['faults'][key]) != sorted(actual['faults'].get(key, [])):
            errs.append(('faults.' + key, expected['faults'][key],
                         actual['faults'].get(key)))
    if len(expected['snapshots']) != len(actual.get('snapshots', [])):
        errs.append(('nsnap', len(expected['snapshots']), len(actual.get('snapshots', []))))
    for es, as_ in zip(expected['snapshots'], actual.get('snapshots', [])):
        if es['id'] != as_.get('id'):
            errs.append(('snap.id', es['id'], as_.get('id')))
        if es['demands'] != as_.get('demands'):
            errs.append(('demands', es['demands'], as_.get('demands')))
        if es['links'] != as_.get('links'):
            errs.append(('links', es['links'], as_.get('links')))
        if es['verdict'] != as_.get('verdict'):
            errs.append(('verdict', es['verdict'], as_.get('verdict')))
    return errs
PYEOF
