#!/usr/bin/env python3
import json, random, sys, time
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tmp')
import analyze
from analyze import parse_request, solve
from brute import brute, compare
import gen

def check_witness(inst, w, k):
    """Independent semantic validation of a witness (like check_sanity)."""
    from fractions import Fraction
    coms = inst['commodities']; edges = inst['edges']; snaps = inst['snapshots']
    assert len(w['demands']) == len(snaps)
    assert len(w['links']) == len(snaps)
    faulty = set()
    for s, q, links in zip(snaps, w['demands'], w['links']):
        assert len(q) == len(coms)
        assert all(type(v) is int and b[0] <= v <= b[1] for v, b in zip(q, s['bounds']))
        loads = {e['id']: Fraction(0) for e in edges}
        metrics = {}
        for c, v in zip(coms, q):
            metrics[('demand', c['id'])] = Fraction(v)
            W = sum(t['weight'] for t in c['routes'])
            for r in c['routes']:
                amt = Fraction(v * r['weight'], W)
                for e in r['edges']:
                    loads[e] += amt
        for n in inst['nodes']:
            metrics[('ingress', n)] = sum((Fraction(v) for c, v in zip(coms, q)
                                           if c['source'] == n), Fraction(0))
            metrics[('egress', n)] = sum((Fraction(v) for c, v in zip(coms, q)
                                          if c['target'] == n), Fraction(0))
        for e in edges:
            metrics[('link', e['id'])] = loads[e['id']]
        assert all(loads[e['id']] <= e['capacity'] for e in edges), 'capacity'
        want = ['%d/%d' % (loads[e['id']].numerator, loads[e['id']].denominator)
                for e in edges]
        assert links == want, (links, want)
        for o in s['observations']:
            v = metrics[(o['metric'], o['target'])]
            if not (o['lower'] <= v <= o['upper']):
                assert o['domain'] is not None, 'violated trusted observation'
                faulty.add(o['domain'])
    assert len(w['faults']) == len(set(w['faults']))
    assert set(w['faults']) == faulty, (w['faults'], faulty)
    assert len(faulty) == k, (faulty, k)

def main():
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 200
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    rnd = random.Random(seed)
    bad = 0
    stats = {}
    t0 = time.time()
    slowest = (0, None)
    for i in range(n):
        inst_raw = gen.gen_instance(rnd,
                                    max_nodes=rnd.choice([2,3,4,5]),
                                    max_edges=rnd.choice([0,2,4,6]),
                                    max_coms=rnd.choice([0,1,2,3]),
                                    max_snaps=rnd.choice([1,2,3]),
                                    max_doms=rnd.choice([0,1,2,3,4]),
                                    max_bound=rnd.choice([0,2,4,6]),
                                    max_obs=rnd.choice([0,2,4,6]))
        raw = json.dumps(inst_raw)
        try:
            inst = parse_request(json.loads(raw))
        except analyze.Invalid as exc:
            print('generated invalid instance!', json.dumps(inst_raw)[:600])
            bad += 1
            continue
        exp = brute(inst)
        if exp is None:
            continue
        st = time.time()
        act = solve(inst)
        el = time.time() - st
        if el > slowest[0]:
            slowest = (el, inst['id'])
        errs = compare(exp, act)
        stats[exp['status']] = stats.get(exp['status'], 0) + 1
        if exp['status'] in ('unique', 'ambiguous'):
            try:
                check_witness(inst, act['witness'], act['min_faults'])
                if exp['status'] == 'unique':
                    if act['alternative'] is not None:
                        errs.append(('alt should be null', 1, 0))
                else:
                    if act['alternative'] is None:
                        errs.append(('alt missing', 1, 0))
                    else:
                        check_witness(inst, act['alternative'], act['min_faults'])
                        if act['witness']['demands'] == act['alternative']['demands']:
                            errs.append(('alt same demands', 1, 0))
            except AssertionError as e:
                errs.append(('witness', str(e), ''))
            except Exception as e:
                errs.append(('witness-exc', repr(e), ''))
        if errs:
            bad += 1
            print('MISMATCH', json.dumps(inst_raw))
            print(' exp', json.dumps(exp)[:800])
            print(' act', json.dumps(act)[:800])
            print(' errs', errs)
            if bad > 4:
                break
    print('done %d cases, %d bad, %.1fs, stats=%s, slowest=%.2fs' %
          (n, bad, time.time() - t0, stats, slowest[0]))

main()
